        'meta_description' => 'FAIA, LIVA, AED, Peppol, ViDA, Artikel 56 ter, VIES… Kloer Definitiounen vun all den Term vun der Rechnungsstellung an der TVA zu Lëtzebuerg fir Freelancer, KMU a Fiduciairen.',
