                'description' => 'Offene XML-Standard (OASIS), deen elektronesch Geschäftsdokumenter definéiert (Rechnung, Avoir, Bestellung). De Peppol-BIS-Format, deen an Europa fir d\'E-Rechnung genotzt gëtt, baséiert op UBL 2.1.',
