    'legal_terms_s1_title' => '1. Géigestand',
    'legal_terms_s1_p1' => 'Dës Allgemeng Geschäftsbedingungen (nodréiglech "AGB") definéieren d\'Konditioune, ënner deenen den Alexandre Beaudier, Operateur vum Service faktur.lu (nodréiglech "den Ubidder"), de Notzer (nodréiglech "den Notzer" oder "de Client") en Online-Rechnungsservice ubitt.',
    'legal_terms_s1_p2' => 'D\'Aschreiwung an d\'Notzung vum Service implizéieren déi voll Akzeptatioun vun dësen AGB.',

    'legal_terms_s2_title' => '2. Definitiounen',
    'legal_terms_s2_li1_label' => 'Service:',
    'legal_terms_s2_li1_text' => 'D\'Webapplikatioun faktur.lu fir d\'Erstellen an d\'Verwalte vu Rechnungen, Offerten, Gutschrëften an Zäiterfaassung.',
    'legal_terms_s2_li2_label' => 'Notzer / Client:',
    'legal_terms_s2_li2_text' => 'All natierlech oder juristesch Persoun, déi e Kont op faktur.lu erstallt huet.',
    'legal_terms_s2_li3_label' => 'Kont:',
    'legal_terms_s2_li3_text' => 'De perséinleche Beräich vum Notzer, deen iwwer seng Zougangsdaten zougänglech ass.',
    'legal_terms_s2_li4_label' => 'Abonnement:',
    'legal_terms_s2_li4_text' => 'Bezuelten Plang, deen Zougang zu erweiderten Funktiounen vum Service gëtt.',
    'legal_terms_s2_li5_label' => 'Inhalt:',
    'legal_terms_s2_li5_text' => 'D\'Donnéeën, déi vum Notzer aginn ginn (Rechnungen, Clienten, asw.).',

    'legal_terms_s3_title' => '3. Accès zum Service',
    'legal_terms_s3_1_title' => '3.1 Aschreiwung',
    'legal_terms_s3_1_p' => 'Den Accès zum Service erfuerdert d\'Erstelle vun engem Kont. Den Notzer muss exakt a komplett Informatiounen ubidden, besonnesch eng valabel E-Mail-Adress.',
    'legal_terms_s3_2_title' => '3.2 Berechtegungskonditiounen',
    'legal_terms_s3_2_p' => 'De Service ass fir Beruffsleit gedacht (Entreprisen, Onofhängeger, fräi Beruffer). Den Notzer erkläert:',
    'legal_terms_s3_2_li1' => 'Erwuesse a juristesch fäeg ze sinn',
    'legal_terms_s3_2_li2' => 'Am Kader vu senger beruflecher Aktivitéit ze handelen',
    'legal_terms_s3_2_li3' => 'D\'noutwendeg Autorisatiounen ze hu fir de Service ze notzen',
    'legal_terms_s3_3_title' => '3.3 Kontosécherheet',
    'legal_terms_s3_3_p' => 'Den Notzer ass verantwortlech fir d\'Vertraulechkeet vu senge Zougangsdaten. All Notzung vu sengem Kont gëtt als vun him gemaach betruecht. Hie muss faktur.lu direkt iwwer all onerlaabt Notzung informéieren.',

    'legal_terms_s4_title' => '4. Beschreiwung vum Service',
    'legal_terms_s4_p' => 'faktur.lu ass eng Online-Rechnungssoftware (SaaS), déi de Lëtzebuerger an europäesche Ufuerderungen entsprécht, an déi besonnesch bitt:',
    'legal_terms_s4_li1' => 'Erstellen a Verwalte vu Rechnungen, Offerten a Gutschrëften',
    'legal_terms_s4_li2' => 'Verwaltung vu Clienten a Kontakter',
    'legal_terms_s4_li3' => 'FAIA-Export konform mat der AED Lëtzebuerg',
    'legal_terms_s4_li4' => 'Zäiterfaassung a Rechnungsgeneréierung',
    'legal_terms_s4_li5' => 'Versenden vu Rechnungen per E-Mail',
    'legal_terms_s4_li6' => 'Dashboard a Statistiken',
    'legal_terms_s4_li7' => 'Geséchert Comptablen-Accès',

    'legal_terms_s5_title' => '5. Abonnementer a Präisser',
    'legal_terms_s5_1_title' => '5.1 Abonnementspläng',
    'legal_terms_s5_1_p' => 'De Service bitt verschidde Pläng un:',
    'legal_terms_s5_plan1_title' => 'Entdeckung (Gratis)',
    'legal_terms_s5_plan1_desc' => 'Limitéiert Funktiounen, ideal fir de Service ze testen.',
    'legal_terms_s5_plan2_title' => 'Professional',
    'legal_terms_s5_plan2_desc' => 'Komplett Funktiounen fir Onofhängeger a KMU. Präis op der Präisser-Säit ugewisen.',
    'legal_terms_s5_2_title' => '5.2 Präisser',
    'legal_terms_s5_2_p1' => 'D\'Präisser ginn op der Säit netto an Euro (ouni TVA) ugewisen. Déi uwendbar TVA gëtt bei der Bezuelung no dem zu Lëtzebuerg gëltege Saz (17%) derbäigerechent.',
    'legal_terms_s5_2_p2' => 'Den Ubidder behält sech d\'Recht vir, seng Präisser jiddwerzäit z\'änneren. Präisännerunge ginn op d\'mannst 30 Deeg virum Inkrafttriede per E-Mail matgedeelt a gëllen fir déi nächst Verlängerung vum Abonnement.',
    'legal_terms_s5_3_title' => '5.3 Dauer a Verlängerung',
    'legal_terms_s5_3_p' => 'Abonnementer ginn no Wahl vum Notzer fir e Mount oder e Joer ofgeschloss. Si verlängere sech automatesch um Enn vu jider Period, ausser bei Kënnegung gemäss Artikel 13.',
    'legal_terms_s5_4_title' => '5.4 Testperiod',
    'legal_terms_s5_4_p' => 'Eng gratis Testperiod kann ugebuede ginn. Um Enn vun dëser Period gëtt den Abonnement bezuelbar, ausser bei Kënnegung. Den Notzer gëtt virum Enn vun der Testperiod informéiert.',

    'legal_terms_s6_title' => '6. Bezuelung',
    'legal_terms_s6_1_title' => '6.1 Bezuelmëttelen',
    'legal_terms_s6_1_p' => 'D\'Bezuelung geschitt per Kreditkaart (Visa, Mastercard, American Express) iwwer déi geséchert Stripe-Plattform. D\'Transaktioune sinn verschlësselt a konform mat de PCI-DSS-Standarden.',
    'legal_terms_s6_2_title' => '6.2 Rechnungsstellung',
    'legal_terms_s6_2_p' => 'Eng elektronesch Rechnung gëtt no jider Bezuelung erstallt an ass am Clientberäich verfügbar. Si kann och op Ufro per E-Mail geschéckt ginn.',
    'legal_terms_s6_3_title' => '6.3 Bezuelungsausfall',
    'legal_terms_s6_3_p' => 'Bei engem Bezuelungsausfall gëtt den Notzer notifizéiert an huet 7 Deeg fir d\'Bezuelung ze regelen. No dëser Frist gëtt den Accès zu de bezuelte Funktiounen suspendéiert. D\'Donnéeë gi fir weider 30 Deeg behale, ier se eventuell geläscht ginn.',
    'legal_terms_s6_4_title' => '6.4 TVA',
    'legal_terms_s6_4_p' => 'Fir Beruffsclienten, déi an engem anere EU-Memberstaat etabléiert sinn an déi eng valabel intra-Communautaire TVA-Nummer hunn, gëtt d\'TVA net berechent (Reverse Charge). De Client muss d\'TVA dann a sengem Land deklaréieren.',

    'legal_terms_s7_title' => '7. Widderrufsrecht',
    'legal_terms_s7_warn_title' => 'Wichteg Informatioun fir Konsumenten',
    'legal_terms_s7_warn_p' => 'Gemäss Artikel L. 221-28 vum franséische Konsumentegesetzbuch a glaichwäertegen Dispositiounen aus dem Lëtzebuerger Recht gëllt d\'Widderrufsrecht net fir Verträg fir d\'Liwwerung vun digitalen Inhalter, déi net op engem kierperleche Medium geliwwert ginn, wann d\'Ausféierung mat ausdrécklecher virhärger Zoustëmmung vum Konsument ugefaangen huet.',
    'legal_terms_s7_p1' => 'Mat dem Ofschloss vun engem bezuelten Abonnement erkennt den Notzer un, datt:',
    'legal_terms_s7_li1' => 'hien ausdrécklech déi direkt Ausféierung vum Service verlaangt',
    'legal_terms_s7_li2' => 'hien ausdrécklech op säi 14-deegegt Widderrufsrecht verzicht, soubal den Accès zum bezuelte Service aktivéiert ass',
    'legal_terms_s7_p2' => 'Fir Joresabonnementer kann awer eng prorata temporis Rembourséierung op Ufro an deenen éischten 30 Deeg no der Ënnerschreiwung gewährt ginn, ënner der Bedingung vun enger raisonnabeler Notzung vum Service.',

    'legal_terms_s8_title' => '8. Flichte vum Notzer',
    'legal_terms_s8_p' => 'Den Notzer verflicht sech:',
    'legal_terms_s8_li1' => 'Bei der Aschreiwung exakt Informatiounen ze ginn an se op den neiste Stand ze halen',
    'legal_terms_s8_li2' => 'De Service no sengem Zweck ze notzen (professionnell Rechnungsstellung)',
