    'legal_terms_s8_li5' => 'D\'Steier- a Buchhaltungsgesetzgebung respektéieren, déi op seng Aktivitéit applicabel ass',
    'legal_terms_s8_li6' => 'Net ze probéieren d\'Sécherheet oder de Fonctionnement vum Service ze kompromittéieren',
    'legal_terms_s8_li7' => 'Den Accès zum Service net weiderzeverkafen oder ënnerzelizenzéieren',

    'legal_terms_s9_title' => '9. Flichte vu faktur.lu',
    'legal_terms_s9_1_title' => '9.1 Verfügbarkeet vum Service',
    'legal_terms_s9_1_p1' => 'Den Ubidder verflicht sech, déi néideg Mëttelen anzesetzen, fir d\'Verfügbarkeet vum Service 24/7 ze garantéieren, mat enger Ziel-Verfügbarkeet vun 99,5% (ouni geplangten Ënnerhalt).',
    'legal_terms_s9_1_p2' => 'Ënnerbriechunge fir Ënnerhalt ginn, wann méiglech, ausserhalb vun de Geschäftszäite geplangt a virdru ugekënnegt.',
    'legal_terms_s9_2_title' => '9.2 Support',
    'legal_terms_s9_2_p_before' => 'Technesche Support ass per E-Mail verfügbar op',
    'legal_terms_s9_2_p_after' => '. D\'Reaktiounszäit hänkt vum Abonnementsplang of.',
    'legal_terms_s9_3_title' => '9.3 Sécherheet a Backup',
    'legal_terms_s9_3_p' => 'Den Ubidder setzt Sécherheetsmoossnamen am Aklang mat den Industriestandarden ëm a féiert reegelméisseg Datesécherungen duerch.',

    'legal_terms_s10_title' => '10. Donnéeën a Besëtz',
    'legal_terms_s10_1_title' => '10.1 Besëtz vun den Donnéeën',
    'legal_terms_s10_1_p' => 'Den Notzer bleift Besëtzer vun all den Donnéeën, déi hien an de Service agitt (Rechnungen, Clientinformatiounen, asw.). Den Ubidder kritt keng Rechter op dës Donnéeën.',
    'legal_terms_s10_2_title' => '10.2 Notzungslizenz',
    'legal_terms_s10_2_p' => 'Den Notzer gëtt dem Ubidder eng limitéiert Lizenz, fir seng Donnéeën nëmmen am Kader vum Service ze veraarbeiten.',
    'legal_terms_s10_3_title' => '10.3 Daten-Export',
    'legal_terms_s10_3_p' => 'Den Notzer kann seng Daten zu all Moment a Standardformater exportéieren (PDF, CSV, FAIA XML).',
    'legal_terms_s10_4_title' => '10.4 Dateschutz',
    'legal_terms_s10_4_p_before' => 'D\'Veraarbechtung vu perséinlechen Donnéeën gëtt vun eiser',
    'legal_terms_s10_4_link' => 'Dateschutzpolitik',
    'legal_terms_s10_4_p_after' => ' geregelt.',

    'legal_terms_s10_5_title' => '10.5 RGPD Subtraitement (DPA)',
    'legal_terms_s10_5_p_before' => 'Wann den Notzer Verantwortlechen am Sënn vum Reglement (EU) 2016/679 (RGPD) ass an faktur.lu perséinlech Donnéeën a sengem Numm veraarbecht, sinn d\'Parteien d\'accord, datt den ',
    'legal_terms_s10_5_link' => 'Donnéeëveraarbechtungsofkommen (DPA)',
    'legal_terms_s10_5_p_after' => ', zu all Moment op der Säit konsultéierbar, en integralen Deel vun dësen AGB ass. Andeems hien d\'AGB akzeptéiert, akzeptéiert den Notzer och d\'DPA an senger aktueller Versioun. Eng separat handschrëftlech Ënnerschrëft kann op Ufro fir Notzer gemaach ginn, déi se fir hir eege Konformitéit brauchen (notamment Treihandgesellschaften an audéiert Cliente).',

    'legal_terms_s11_title' => '11. Geeschtegt Eegentum',
    'legal_terms_s11_p1' => 'De Service, abegraff säi Quellcode, säin Interface, seng Funktiounen, säin Design, seng Markenzeechen a Logoen, ass exklusiv Eegentum vum Ubidder oder senge Partner.',
    'legal_terms_s11_p2' => 'Den Abonnement gëtt nëmmen e perséinlecht, net-exklusiivt an net-iwwerdrobart Notzungsrecht um Service fir d\'Dauer vum Abonnement.',

    'legal_terms_s12_title' => '12. Haftungsbeschränkung',
    'legal_terms_s12_1_title' => '12.1 Garantien',
    'legal_terms_s12_1_p' => 'Den Ubidder verflicht sech, de Service mat Suergfalt ze liwweren. De Service gëtt awer "wéi en ass" geliwwert an den Ubidder garantéiert net, datt hien all spezifesch Bedierfnesser vum Notzer wäert decken.',
    'legal_terms_s12_2_title' => '12.2 Beschränkung',
    'legal_terms_s12_2_p1' => 'D\'Haftung vum Ubidder ass op direkt Schied limitéiert an däerf de Betrag vun de Summen, déi vum Notzer an de leschten 12 Méint bezuelt goufen, net iwwerschreiden.',
    'legal_terms_s12_2_p2' => 'Den Ubidder ka net verantwortlech gemaach gi fir:',
    'legal_terms_s12_2_li1' => 'Indirekt Schied (Verloscht vun Ëmsaz, kommerziellen Schued, asw.)',
    'legal_terms_s12_2_li2' => 'D\'Genauegkeet vun den Donnéeën, déi vum Notzer aginn goufen',
    'legal_terms_s12_2_li3' => 'D\'steierlech Konformitéit vu Rechnungen, déi vum Notzer ausgestallt goufen',
    'legal_terms_s12_2_li4' => 'Ënnerbriechungen duerch Drëtter (Hostingubidder, ISP, asw.)',
    'legal_terms_s12_2_li5' => 'Fäll vu Force majeure',
    'legal_terms_s12_3_title' => '12.3 Haftung vum Notzer',
    'legal_terms_s12_3_p' => 'Den Notzer ass eleng verantwortlech fir d\'Konformitéit vu senge Rechnunge mat den uwendbare steierlechen Reglementatiounen. De Service ass en Outil, deen d\'Rechnungsstellung erliichtert, awer keng Steier- oder Rechtsberodung duerstellt.',

    'legal_terms_s13_title' => '13. Kënnegung',
    'legal_terms_s13_1_title' => '13.1 Kënnegung duerch den Notzer',
    'legal_terms_s13_1_p1' => 'Den Notzer kann säin Abonnement zu all Moment vu sengem Clientberäich aus kënnegen. D\'Kënnegung gëtt um Enn vun der lafender Period effektiv. Den Notzer behält den Accès zum Service bis zu dësem Datum.',
    'legal_terms_s13_1_p2' => 'Schonn bezuelte Summen ginn net rembourséiert, ausser anescht virgesinn an Artikel 7.',
    'legal_terms_s13_2_title' => '13.2 Kënnegung duerch den Ubidder',
    'legal_terms_s13_2_p' => 'Den Ubidder kann den Abonnement bei folgende Fäll kënnegen:',
    'legal_terms_s13_2_li1' => 'Verletzung vun dësen AGB',
    'legal_terms_s13_2_li2' => 'Net regulariséierte Bezuelungsausfall',
    'legal_terms_s13_2_li3' => 'Bedréiglech oder mëssbräichlech Notzung vum Service',
    'legal_terms_s13_2_li4' => 'Astellung vum Service (mat 3 Méint Virukënnegung)',
    'legal_terms_s13_3_title' => '13.3 Konsequenze vun der Kënnegung',
    'legal_terms_s13_3_p' => 'No der Kënnegung huet den Notzer 30 Deeg, fir seng Donnéeën z\'exportéieren. No dëser Frist kënnen d\'Donnéeë geläscht ginn, ënner Berücksichtigung vun de legalen Opbewahrungsflichten.',

    'legal_terms_s14_title' => '14. Ännerunge vun den AGB',
    'legal_terms_s14_p1' => 'Den Ubidder behält sech d\'Recht vir, dës AGB z\'änneren. D\'Ännerunge ginn per E-Mail an/oder duerch Affichage am Service op d\'mannst 30 Deeg virum Inkrafttriede matgedeelt.',
    'legal_terms_s14_p2' => 'Déi weider Notzung vum Service no dem Inkrafttriede vun den Ännerunge gëllt als Akzeptanz vun den neien AGB. Bei Net-Averständnis kann den Notzer säin Abonnement kënnegen.',

    'legal_terms_s15_title' => '15. Uwendbaart Recht a Geriichtsbarkeet',
    'legal_terms_s15_p1' => 'Dës AGB ënnerleien dem Lëtzebuerger Recht.',
    'legal_terms_s15_p2' => 'Bei engem Streit wäerten d\'Parteie probéieren, eng giedlech Léisung ze fannen. Anerefalls sinn ausschliisslech d\'Geriichter vu Lëtzebuerg zoustänneg.',
    'legal_terms_s15_p3_label' => 'Mediatioun:',
    'legal_terms_s15_p3_text' => 'Gemäss der europäescher Reglementatioun kann de Konsument am Fall vun engem net geléisten Streit de Mediatiounsservice gratis benotzen. Online-Plattform fir Sträitschlichtung:',

