    'recurring_invoice_how_it_works_title' => 'Wéi funktionéieren wiederkehrend Rechnungen?',
    'recurring_invoice_how_p1_html' => 'Eng Widderhuelung ass eng <strong>Schabloun</strong>, déi automatesch nei Rechnungen a reegelméissegen Intervalle generéiert (wëchentlech, monatlech, véierteljäerlech oder jäerlech).',
    'recurring_invoice_how_p2_html' => 'All Dag ëm <strong>06:00</strong> kontrolléiert d\'System déi <strong>aktiv</strong> Widderhuelungen, deenen hire nächsten Datum ukomm ass, an erstellt déi entspriechend Rechnung. Je no gewielten Optiounen:',
    'recurring_invoice_how_li1_html' => '<strong>Keng Optioun</strong> → d\'Rechnung gëtt als <strong>Brouillon</strong> erstallt; Dir finaliséiert a verschéckt se manuell.',
    'recurring_invoice_how_li2_html' => '<strong>Automatesch Finaliséierung</strong> → d\'Rechnung gëtt automatesch <strong>finaliséiert</strong> (Nummer attribuéiert); et bleift just nach se ze verschécken.',
    'recurring_invoice_how_li3_html' => '<strong>Auto-Finaliséierung + Auto-Versand</strong> → d\'Rechnung gëtt ouni weider Aktioun <strong>per E-Mail</strong> un de Client verschéckt.',
    'recurring_invoice_how_p3_html' => 'Den Datum vun der nächster Rechnung gëtt no all Generatioun automatesch erhéicht. Wann Dir en Enndatum festleet, deaktivéiert sech d\'Widderhuelung vu selwer, wann dëst iwwerschratt ass.',
